                    .replace(/\{key\}/g, String(ticketKey))
                    .replace(/\{issueNumber\}/g, String(issueNumber !== null ? issueNumber : (prAnchoredFallback ? '' : ticketKey)))
                    .replace(/\{prNumber\}/g, String(it.prNumber || ''));
