    var ruleSelfManagesLabel = rule.localTeammate && ruleTargetSelfManagesLabel(rule);
    if (ruleSelfManagesLabel) {
        console.log('  ℹ️  Target job self-manages "' + (rule.addLabel || rule.addLabels) +
