                        ' preempts the FIFO queue — ' + (matched.length - keptCount) +
                        ' non-blocker PR(s) yield the slot (owner rule 2026-10-08)');
                }
            });
        }
    } else {
        matched.sort(function (a, b) { return (a.prNumber || 0) - (b.prNumber || 0); });
    }

    return matched.slice(0, limit);
}

