    var workflowRef  = rule.workflowRef  || 'main';
    var it0 = item || {};
    workflowRef = String(workflowRef)
        .replace(/\{branch\}/g, String(it0.branch || ''))
        .replace(/\{prNumber\}/g, String(it0.prNumber || ''));
    if (!workflowRef) workflowRef = 'main';
