        // would re-fire a duplicate leg on the next quiet tick.
        var altKeys = crossAnchorKeys(item);
        for (var altIx = 0; altIx < altKeys.length; altIx++) {
            if (hasActiveTargetWorkflowRun(scm, workflowFile, resolvedCf, altKeys[altIx])) {
