    '    var d = args.descriptor;',
    "    var query = 'repo:' + args.repo.owner + '/' + args.repo.repo +",
    "        ' is:issue is:open ' +",
    "        (d.kind === 'label' ? 'label:\"' + d.label + '\"' : 'assignee:' + args.assignee);",
    '    return { descriptor: d, items: asList(parseMcp(github_search_issues({ query: query }))) };',
