            removeRuleLabel(key, label, rule, effectiveRepoInfo);
            auditReworkConsumption(effectiveRepoInfo, ticket, label, 'cross-anchor');
        });
    }

    if (triggered) {
        processedKeys.push(key);
        if (!rule.localTeammate && workflowBudget) workflowBudget.remaining -= 1;
    }
}

