var _priorityIssueLabelCache = { entries: {} };

function cachedIssueLabels(repoInfo, issueNumber) {
    var key = (repoInfo.owner || '') + '/' + (repoInfo.repo || '') +
        ':issueLabels:' + issueNumber;
