function ghostGuardMarks(bodies) {
    var out = { deferred: {}, cleaned: {} };
    (bodies || []).forEach(function (body) {
        var s = String(body == null ? '' : body);
        var m;
        GHOST_GUARD_DEFER_RE.lastIndex = 0;
