var GHOST_GUARD_CLEAN_RE = /🧹 ghost-guard clean ([0-9a-f]{7,40}) — (\d+) orphaned check-run\(s\) concluded at (\S+)/g;

function ghostGuardDeferMarkerLine(headSha, runId, atIso) {
