function resolveHeadSha(repoInfo, ticket) {
    // gh-1394 (live fa 2026-10-07): queryPrs builds PR tickets with
    // pr:null and NO headSha — the sha is attached lazily, and only when
    // a rule's guards need mergeState/checks (prStatus). The park-reset
    // rule's query {labels, notLabels, draft} carries no such guard, so
    // the RESET ladder saw uHead=null and failed closed on EVERY tick
    // with ZERO API calls (live: nine parked guest PRs, every head chain
    // depth-2 with fresh human pushes; manual probes all succeeded — the
    // tick simply never issued them; the ⚠️ landed ~1s after the events
    // probe, no /commits call in sight). Resolve the head at the
    // consumption site: one github_get_pr when the ticket carries none.
    var head = (ticket && ticket.pr && ticket.pr.headSha) || (ticket && ticket.headSha);
    if (head || !ticket || !ticket.prNumber) return head || null;
    try {
        var pr = mcpParse(github_get_pr({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: ticket.prNumber
        }));
        var resolved = (pr && pr.head && pr.head.sha) || null;
        if (resolved) {
            console.log('  ℹ️  ' + (ticket.key || ('pr-' + ticket.prNumber)) +
                ': head sha resolved via github_get_pr (' + resolved.slice(0, 8) + ')');
        }
        return resolved;
    } catch (eRhs) {
        console.warn('  ⚠️  head sha resolve failed for ' +
            (ticket.key || ('pr-' + ticket.prNumber)) + ': ' + (eRhs.message || eRhs));
        return null;
    }
}

// gh-846: FRESH PR head read for the post-refresh stale-cancel. Deliberately
// bypasses the ticket's cached headSha: the silent refresh just moved the
// head, so any cached sha is the PRE-refresh one — cancelling against it
// would select runs on the CURRENT head (AC4: never touch those). One
// github_get_pr per refreshed PR. Fail CLOSED (null): without the true new
// head the stale selection cannot run safely — the dead-head runs wait one
// tick; a wrongful cancel is the worse failure.
function freshHeadSha(repoInfo, prNumber) {
    try {
        var pr = mcpParse(github_get_pr({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: prNumber
        }));
        var sha = (pr && pr.head && pr.head.sha) || null;
        if (!sha) {
            console.warn('  ⚠️  post-refresh head read for pr-' + prNumber +
                         ' returned no head sha — stale-cancel skipped this tick');
        }
        return sha;
    } catch (eFresh) {
        console.warn('  ⚠️  post-refresh head read failed for pr-' + prNumber +
                     ': ' + (eFresh.message || eFresh) + ' — stale-cancel skipped this tick');
        return null;
    }
}

function parkedSince(repoInfo, prNumber) {
    // Sticky-park RESET probe: ISO time of the newest validation_failed
    // 'labeled' event — the park's start. The RESET requires the clearing
    // push to be NEWER than this moment; the head that the park was set
    // on predates the event by definition, so an old red head cannot
    // clear its own park. Returns the ISO string or null (fail closed).
    try {
        var res = cli_execute_command({
            command: 'gh api "repos/' + repoInfo.owner + '/' + repoInfo.repo +
                     '/issues/' + prNumber +
                     '/events?per_page=100" --jq \'[.[] | select(.event == "labeled" and .label.name == "validation_failed") | .created_at] | max // ""\''
        });
        var out = String((res || {}).output || (res || {}).stdout || res || '')
            .trim().replace(/^"|"$/g, '');
        return out || null;
    } catch (e) {
        console.warn('  ⚠️  park-time probe failed: ' + (e.message || e));
        return null;
    }
}

function parkedHeadSha(repoInfo, prNumber) {
    // Sticky-park RESET probe v2 (dmtools-agents#633, live fa#1139
    // 2026-10-02): the head sha the NEWEST park comment recorded
    // ('parked-head: <sha>'). The park verdict is only valid for THAT
    // sha; a silent rebase moves the head to a sha that has never been
    // validated, and the sticky park must not outlive its verdict.
    // Returns the 40-hex sha or '' when no park comment is found.
    // Probe failure returns null (fail closed: no sha → no head-change
    // clear; the human-push RESET path still applies).
    try {
        var res = github_get_pr_comments({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestId: prNumber
        });
        var obj = typeof res === 'string' ? JSON.parse(res) : (res || []);
        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        var sha = '';
