            var b = String((c && c.body) || '');
            if (b.indexOf('parked-head: ') === -1) return;
            var tail = b.slice(b.lastIndexOf('parked-head: ') + 13);
            var m = /^([0-9a-f]{40})/.exec(tail.trim());

