function capOf(jobParams) {
    if (String((jobParams || {}).triggerFailParkCap) === 'false') return 0;
    var n = (jobParams || {}).triggerFailParkCap;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    if (typeof n !== 'number' || isNaN(n) || n <= 0) return 3;
    return Math.floor(n);
