            assert.equal(mod.capOf({ triggerFailParkCap: false }), 0);
            assert.equal(mod.capOf({ triggerFailParkCap: 0 }), 0);
            assert.equal(mod.capOf({ triggerFailParkCap: -1 }), 0);
        });
    });
});
